/**
 * @description Field paths of the Selected Fields payload: splitting, checking against the Schema (up to 5 lookups) and
 * reading values from a record. Needs no data.
 * @group Integration Hub
 */
public with sharing class IntegrationHubPayloadPaths {

    private static final Integer MAX_LOOKUPS = 5;

    /**
     * @description Splits Payload Fields into unique paths.
     * @param text paths separated by commas, semicolons or new lines
     * @return the paths, in order
     */
    public static List<String> split(String text) {
        List<String> paths = new List<String>();
        Set<String> seen = new Set<String>();
        for (String raw : String.isBlank(text) ? new List<String>() : text.split('[,\\n\\r;]')) {
            String path = raw.trim();
            if (String.isNotBlank(path) && seen.add(path.toLowerCase())) {
                paths.add(path);
            }
        }
        return paths;
    }

    /**
     * @description Checks field paths against the object (Schema only).
     * @param objectName the object API name
     * @param paths the field paths
     * @return null when every path is valid, otherwise the problem
     */
    public static String invalid(String objectName, List<String> paths) {
        Schema.SObjectType root = String.isBlank(objectName) ? null : Schema.getGlobalDescribe().get(objectName);
        if (root == null) {
            return paths.isEmpty() ? null : 'Unknown object: ' + objectName;
        }
        List<String> bad = new List<String>();
        for (String path : paths) {
            if (!isValid(root, path)) {
                bad.add(path);
            }
        }
        return bad.isEmpty() ? null : 'Invalid payload fields on ' + objectName + ': ' + String.join(bad, ', ');
    }

    /**
     * @description Reads a value by a dotted path through lookups, e.g. Owner.Name.
     * @param rec the record (may be null)
     * @param path the field path
     * @return the value, or null when the record or a lookup on the way is empty
     */
    public static Object read(SObject rec, String path) {
        List<String> parts = path.split('\\.');
        SObject current = rec;
        for (Integer i = 0; i < parts.size() - 1 && current != null; i++) {
            current = current.getSObject(parts[i]);
        }
        return current == null ? null : current.get(parts[parts.size() - 1]);
    }

    private static Boolean isValid(Schema.SObjectType root, String path) {
        List<String> parts = path.split('\\.');
        Schema.SObjectType current = parts.size() > MAX_LOOKUPS + 1 ? null : root;
        for (Integer i = 0; i < parts.size() - 1 && current != null; i++) {
            current = parentType(current, parts[i]);
        }
        return current != null && current.getDescribe(SObjectDescribeOptions.DEFERRED).fields.getMap().containsKey(parts[parts.size() - 1]);
    }

    private static Schema.SObjectType parentType(Schema.SObjectType objType, String relationship) {
        for (Schema.SObjectField f : objType.getDescribe(SObjectDescribeOptions.DEFERRED).fields.getMap().values()) {
            Schema.DescribeFieldResult d = f.getDescribe();
            if (relationship.equalsIgnoreCase(d.getRelationshipName())) {
                return d.getReferenceTo()[0];
            }
        }
        return null;
    }
}
